24	// --describe subprocesses that whole-registry discovery would spawn.
25	EngineDescriptor builtin_qemu() {
26	  EngineDescriptor d;
27	  d.id = "qemu";
28	  d.type = "qemu";
29	  d.kind = "functional";
30	  d.xlen = 64;
31	  d.triggers = {"csr", "pc", "icount", "simpoint"};
32	  d.roles = {"standalone", "fast-leg"};
33	  d.state = {"drain"};
34	  d.source = "built-in";
