123	// `prefix` filters candidate basenames; empty accepts any executable. The
124	// default verilator/build scan passes "sim_"; a user-curated engines dir passes
125	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
126	// lives in the call site, not in this engine-agnostic scanner.
127	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
128	              std::set<std::string>& seen) {
129	  std::error_code ec;
130	  if (!fs::is_directory(dir, ec)) return;
131	
132	  std::vector<fs::path> entries;
133	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
134	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
135	
136	  for (const fs::path& p : entries) {
137	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
138	    if (!is_executable_file(p)) continue;
139	    EngineDescriptor d;
140	    std::string warn;
141	    if (describe_one(p, d, warn)) {
142	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
143	    } else if (!warn.empty()) {
144	      out.warnings.push_back(warn);
145	    }
146	  }
147	}
